from collections import deque

class Solution:
    def canVisitAllRooms(self, rooms: list[list[int]]) -> bool:
        queue, seen = deque([0]), {0}
        while queue:
            for key in rooms[queue.popleft()]:
                if key not in seen:
                    seen.add(key)
                    queue.append(key)
        return len(seen) == len(rooms)
